FIS_QB.push(
/* ---------- U1 · Metodi della fisica ---------- */
{t:"u1a",k:"m",q:"Si versano in una caraffa due bicchieri d'acqua, da 200 mL e da 300 mL, entrambi a 20 °C. Quali grandezze dell'acqua nella caraffa sono uguali a quelle di ciascun bicchiere?",o:["massa e volume","temperatura e densità","volume e temperatura","energia interna e massa","massa e densità"],a:1,s:"Temperatura e densità sono intensive: non dipendono dalla quantità d'acqua. Massa, volume ed energia interna (estensive) si sommano."},
{t:"u1a",k:"c",q:"Una grandezza che raddoppia quando si raddoppia la quantità di materia si dice ____ (estensiva/intensiva).",a:["ESTENSIVA"],s:"Massa, volume, energia, capacità termica sono estensive."},
{t:"u1a",k:"m",q:"Quale delle seguenti grandezze è estensiva?",o:["pressione","densità","temperatura","capacità termica","calore specifico"],a:3,s:"La capacità termica C = c·m cresce con la massa; il calore specifico c, riferito al kg, è invece intensivo."},
{t:"u1a",k:"m",q:"Il rapporto tra due grandezze estensive dello stesso corpo (per esempio massa/volume) è una grandezza:",o:["intensiva","vettoriale","estensiva","fondamentale del SI","sempre adimensionale"],a:0,s:"Raddoppiando il corpo raddoppiano numeratore e denominatore: il rapporto (la densità) non cambia, quindi è intensivo."},
{t:"u1a",k:"m",q:"Quale tra queste grandezze è vettoriale?",o:["energia cinetica","lavoro","pressione","quantità di moto","potenza"],a:3,s:"p = m·v ha la direzione della velocità. Energia, lavoro, potenza e pressione sono scalari."},
{t:"u1a",k:"c",q:"L'unità SI della corrente elettrica, una delle sette fondamentali, è l'____.",a:["AMPERE","A"],s:"m, kg, s, A, K, mol, cd: il volt e il coulomb sono derivati."},
{t:"u1b",k:"m",q:"Ordine di grandezza: quanti battiti compie un cuore in 80 anni di vita, a circa 70 battiti al minuto?",o:["10⁶","10⁷","10⁸","10⁹","10¹²"],a:3,s:"70·60·24·365·80 ≈ 70·5·10⁵·80 ≈ 3·10⁹: ordine 10⁹."},
{t:"u1b",k:"c",q:"(2·10⁻³)·(4·10⁵) = 8·10^x: l'esponente x vale ____.",a:["2","DUE"],s:"Si moltiplicano i coefficienti (2·4 = 8) e si sommano gli esponenti (−3 + 5 = 2)."},
{t:"u1c",k:"m",q:"Due vettori di modulo 4 e 5 formano un angolo di 60°. Il loro prodotto scalare vale:",o:["20","10","17,3","0","9"],a:1,s:"a·b = ab·cos θ = 4·5·0,5 = 10."},
{t:"u1c",k:"m",q:"Due vettori di modulo 2 e 6 formano un angolo di 30°. Il modulo del loro prodotto vettoriale è:",o:["12","10,4","0","3","6"],a:4,s:"|a×b| = ab·sin θ = 2·6·0,5 = 6 (10,4 si ottiene usando per errore il coseno)."},
{t:"u1c",k:"c",q:"Un vettore di modulo 8 forma un angolo di 30° con l'asse x: la sua componente y vale ____.",a:["4","4,0","4.0","QUATTRO"],s:"a_y = a·sin θ = 8·0,5 = 4."},
{t:"u1c",k:"m",q:"Il prodotto vettoriale di due vettori paralleli è:",o:["massimo","uguale al prodotto dei moduli","un vettore parallelo ai due","nullo","uguale al loro prodotto scalare"],a:3,s:"|a×b| = ab·sin θ e sin 0° = 0."},
{t:"u1c",k:"m",q:"In un triangolo rettangolo con ipotenusa di 10 cm, il cateto opposto a un angolo di 30° misura:",o:["8,7 cm","7,1 cm","10 cm","20 cm","5 cm"],a:4,s:"Cateto opposto = ipotenusa·sin 30° = 10·0,5 = 5 cm."},
{t:"u1d",k:"m",q:"Quale grandezza ha dimensioni [M][L]⁻³?",o:["densità","pressione","viscosità","portata","tensione superficiale"],a:0,s:"Densità = massa/volume = kg/m³."},
{t:"u1d",k:"c",q:"La quantità di moto ha dimensioni [M][L][T]^x: l'esponente x vale ____.",a:["-1","−1","MENOUNO"],s:"p = m·v → kg·m/s."},
{t:"u1d",k:"m",q:"La tensione superficiale, misurata in N/m, ha dimensioni:",o:["[M][L][T]⁻²","[M][L]⁻¹[T]⁻²","[M][T]⁻²","[M][L]²[T]⁻²","[M][L]⁻¹[T]⁻¹"],a:2,s:"N/m = (kg·m/s²)/m = kg/s²."},
{t:"u1d",k:"m",q:"Con s spazio, v velocità, a accelerazione e t tempo, quale relazione è dimensionalmente SBAGLIATA?",o:["s = v·t","v = a·t","s = ½·a·t²","v² = 2·a·s","s = a·t"],a:4,s:"a·t è una velocità [L T⁻¹], non una lunghezza: i due membri hanno dimensioni diverse."},
{t:"u1d",k:"c",q:"Il rendimento di una macchina termica, rapporto tra due energie, è una grandezza ____.",a:["ADIMENSIONALE","ADIMENSIONATA","PURA"],s:"Le unità (J/J) si semplificano."},

/* ---------- U2 · Meccanica ---------- */
{t:"u2a",k:"m",q:"Un'auto a 36 km/h frena con decelerazione costante e si ferma in 2 s. Lo spazio di frenata è:",o:["20 m","5 m","36 m","10 m","40 m"],a:3,s:"36 km/h = 10 m/s; velocità media 5 m/s per 2 s = 10 m (area del triangolo nel grafico v-t)."},
{t:"u2a",k:"m",q:"Il grafico velocità-tempo di un corpo è un segmento orizzontale all'altezza di 3 m/s, da t = 0 a t = 4 s. Spazio percorso e accelerazione valgono:",o:["12 m e 0 m/s²","12 m e 3 m/s²","0,75 m e 0 m/s²","7 m e 0 m/s²","3 m e 0,75 m/s²"],a:0,s:"Area del rettangolo = 3·4 = 12 m; pendenza nulla → a = 0."},
{t:"u2a",k:"c",q:"Un corpo percorre 100 m in 20 s e poi altri 100 m in 5 s. La velocità media sull'intero percorso è ____ m/s.",a:["8","OTTO"],s:"Spazio totale / tempo totale = 200/25 = 8 m/s (non la media di 5 e 20 m/s)."},
{t:"u2a",k:"m",q:"Il grafico posizione-tempo di un corpo è una retta orizzontale. Il corpo:",o:["accelera","si muove di moto uniforme","si muove all'indietro","cade liberamente","è fermo"],a:4,s:"La posizione non cambia: pendenza (velocità) nulla."},
{t:"u2b",k:"m",q:"Una provetta in centrifuga ruota a 0,1 m dall'asse con velocità angolare 100 rad/s. L'accelerazione centripeta è:",o:["10 m/s²","100 m/s²","10 000 m/s²","1000 m/s²","10⁵ m/s²"],a:3,s:"a = ω²r = 10⁴·0,1 = 1000 m/s², circa 100 g."},
{t:"u2b",k:"c",q:"Un punto percorre una circonferenza di raggio 2 m a 4 m/s: la sua accelerazione centripeta vale ____ m/s².",a:["8","OTTO"],s:"a = v²/r = 16/2 = 8 m/s²."},
{t:"u2b",k:"m",q:"Un sasso è lanciato orizzontalmente a 15 m/s da un'altezza di 5 m (g = 10 m/s²). A che distanza orizzontale tocca terra?",o:["5 m","30 m","7,5 m","15 m","75 m"],a:3,s:"Tempo di caduta: 5 = ½·10·t² → t = 1 s; in orizzontale 15 m/s · 1 s = 15 m."},
{t:"u2b",k:"m",q:"Un proiettile è lanciato a 20 m/s con un angolo di 30° sull'orizzontale (g = 10 m/s²). L'altezza massima raggiunta è:",o:["5 m","10 m","20 m","15 m","2,5 m"],a:0,s:"v_y = 20·sin 30° = 10 m/s; h = v_y²/(2g) = 100/20 = 5 m."},
{t:"u2b",k:"c",q:"Un corpo in moto circolare uniforme ha periodo 0,5 s: la sua velocità angolare è ω = ____ π rad/s (scrivi il coefficiente di π).",a:["4","QUATTRO"],s:"ω = 2π/T = 2π/0,5 = 4π rad/s."},
{t:"u2c",k:"m",q:"Un ascensore di 500 kg sale a velocità costante (g = 10 m/s²). La tensione del cavo è:",o:["0 N","maggiore di 5000 N","500 N","minore di 5000 N","5000 N"],a:4,s:"Velocità costante → forza risultante nulla: T = mg = 5000 N."},
{t:"u2c",k:"c",q:"Un corpo di 2 kg è tirato con 10 N su un piano orizzontale; l'attrito dinamico vale 4 N. L'accelerazione è ____ m/s².",a:["3","TRE"],s:"Forza risultante 10 − 4 = 6 N; a = 6/2 = 3 m/s²."},
{t:"u2c",k:"m",q:"Sulla Luna g è circa un sesto di quella terrestre. Un astronauta di 90 kg (g Terra = 10 m/s²) sulla Luna ha:",o:["massa 15 kg e peso 900 N","massa e peso nulli","massa 90 kg e peso 900 N","massa 15 kg e peso 150 N","massa 90 kg e peso circa 150 N"],a:4,s:"La massa non cambia; il peso m·g passa da 900 N a circa 150 N."},
{t:"u2d",k:"m",q:"Una persona di 70 kg sale di 4 m in 7 s (g = 10 m/s²). La potenza media sviluppata contro la gravità è:",o:["2800 W","40 W","196 W","4000 W","400 W"],a:4,s:"L = mgh = 2800 J; P = 2800/7 = 400 W."},
{t:"u2d",k:"c",q:"Una molla con k = 400 N/m compressa di 10 cm immagazzina un'energia potenziale elastica di ____ J.",a:["2","DUE"],s:"U = ½kx² = ½·400·0,1² = 2 J."},
{t:"u2e",k:"m",q:"Una massa di 1 kg è in x = 0 e una di 4 kg in x = 10 m. Il centro di massa si trova in:",o:["x = 5 m","x = 2 m","x = 8 m","x = 2,5 m","x = 7,5 m"],a:2,s:"x_cm = (1·0 + 4·10)/5 = 8 m, più vicino alla massa maggiore."},
{t:"u2e",k:"m",q:"Su un sistema di corpi non agiscono forze esterne (al suo interno possono esserci urti o esplosioni). Il suo centro di massa:",o:["resta fermo o si muove di moto rettilineo uniforme","accelera verso il corpo più pesante","si sposta sempre verso l'origine","descrive una circonferenza","coincide sempre con il corpo più pesante"],a:0,s:"Le forze interne non cambiano la quantità di moto totale, quindi la velocità del centro di massa resta costante."},
{t:"u2e",k:"c",q:"Il bicipite si inserisce a 4 cm dal gomito e regge un peso di 20 N tenuto in mano a 36 cm dal gomito. Con l'avambraccio orizzontale (suo peso trascurato) il bicipite deve esercitare ____ N.",a:["180"],s:"F·4 = 20·36 → F = 180 N: la leva di 3° genere è svantaggiosa."},
{t:"u2e",k:"m",q:"La testa (peso 50 N) ha il baricentro 4 cm davanti all'articolazione con l'atlante; i muscoli del collo tirano 5 cm dietro di essa. Forza dei muscoli e genere di leva sono:",o:["62,5 N, leva di 2° genere","50 N, leva di 1° genere","40 N, leva di 3° genere","40 N, leva di 1° genere","62,5 N, leva di 1° genere"],a:3,s:"Fulcro in mezzo → 1° genere; F·5 = 50·4 → F = 40 N."},
{t:"u2e",k:"m",q:"Alzandosi sulle punte dei piedi il fulcro è sulle dita, il peso del corpo cade in mezzo e il tendine d'Achille tira dal tallone. È una leva:",o:["di 1° genere, sempre svantaggiosa","di 3° genere, sempre svantaggiosa","di 1° genere, sempre vantaggiosa","priva di fulcro","di 2° genere, sempre vantaggiosa"],a:4,s:"Resistenza tra fulcro e potenza: 2° genere, braccio della potenza maggiore."},
{t:"u2e",k:"c",q:"Una forza di 40 N è applicata a 0,5 m dal fulcro e forma un angolo di 30° con la congiungente fulcro-punto di applicazione: il momento torcente vale ____ N·m.",a:["10","DIECI"],s:"M = F·r·sin θ = 40·0,5·0,5 = 10 N·m."},
{t:"u2e",k:"m",q:"Su un corpo rigido agiscono due forze uguali e opposte applicate in punti diversi, non sulla stessa retta (una coppia). Il corpo:",o:["resta in equilibrio","trasla","si deforma necessariamente","trasla e ruota","ruota senza traslare"],a:4,s:"Forza risultante nulla (nessuna traslazione) ma momento risultante non nullo: equilibrio traslazionale senza equilibrio rotazionale."},
{t:"u2f",k:"m",q:"Una palla di 0,2 kg arriva su un muro a 10 m/s e rimbalza indietro a 10 m/s. La variazione della quantità di moto ha modulo:",o:["4 kg·m/s","0","2 kg·m/s","20 kg·m/s","40 kg·m/s"],a:0,s:"La velocità cambia verso: Δp = 0,2·10 − (−0,2·10) = 4 kg·m/s."},
{t:"u2f",k:"c",q:"Un fucile di 4 kg spara un proiettile di 10 g a 400 m/s. La velocità di rinculo del fucile è ____ m/s.",a:["1","UNO"],s:"Conservazione: 0,01·400 = 4·v → v = 1 m/s."},
{t:"u2f",k:"m",q:"Atterrando da un salto si piegano le gambe invece di tenerle tese. Questo:",o:["riduce la variazione di quantità di moto","aumenta l'impulso","aumenta la forza media","annulla la quantità di moto iniziale","allunga il tempo di arresto e riduce la forza media"],a:4,s:"Δp è fissato; F·Δt = Δp, quindi un Δt maggiore dà una forza minore."},
{t:"u2f",k:"m",q:"In un urto perfettamente elastico tra due corpi (sistema isolato) si conservano:",o:["solo l'energia cinetica","la quantità di moto e l'energia cinetica","solo la quantità di moto","solo l'energia potenziale","la velocità di ciascun corpo"],a:1,s:"Elastico: si conserva anche l'energia cinetica, oltre alla quantità di moto (che si conserva in ogni urto)."},
{t:"u2f",k:"c",q:"Un corpo di 2 kg passa da 3 m/s a 8 m/s nella stessa direzione: l'impulso ricevuto è ____ N·s.",a:["10","DIECI"],s:"I = Δp = 2·(8 − 3) = 10 N·s."},

/* ---------- U3 · Meccanica dei fluidi ---------- */
{t:"u3a",k:"m",q:"Se l'esperimento di Torricelli si facesse con l'acqua (13,6 volte meno densa del mercurio), l'atmosfera sosterrebbe una colonna alta circa:",o:["76 cm","5,6 cm","1 m","10 m","136 m"],a:3,s:"Stessa pressione ρgh: 0,76 m · 13,6 ≈ 10,3 m."},
{t:"u3a",k:"c",q:"In un manometro a U pieno d'acqua il dislivello tra i due rami è 20 cm (g = 10 m/s²): la pressione relativa misurata è ____ Pa.",a:["2000","2.000","2·10^3"],s:"Δp = ρgh = 1000·10·0,2 = 2000 Pa."},
{t:"u3a",k:"m",q:"Ripetendo l'esperimento di Torricelli in alta montagna, la colonna di mercurio:",o:["si abbassa","resta a 760 mm","si alza","scompare","si alza solo se fa freddo"],a:0,s:"In quota la pressione atmosferica è minore e sostiene una colonna più bassa."},
{t:"u3b",k:"c",q:"Un oggetto pesa 50 N in aria e 30 N quando è completamente immerso in acqua: la sua densità è ____ kg/m³.",a:["2500","2.500"],s:"Spinta 20 N → V = 2 dm³; massa 5 kg → ρ = 5/0,002 = 2500 kg/m³."},
{t:"u3b",k:"m",q:"Un palloncino pieno di elio sale nell'aria perché:",o:["l'elio non ha peso","l'elio è più caldo dell'aria","la pressione interna lo spinge verso l'alto","l'aria lo attrae elettricamente","la spinta dell'aria spostata supera il peso del palloncino"],a:4,s:"Archimede vale anche nei gas: la densità media del palloncino è minore di quella dell'aria."},
{t:"u3c",k:"m",q:"In una stenosi il raggio dell'arteria si dimezza. A parità di portata, la velocità del sangue nel tratto ristretto:",o:["raddoppia","si dimezza","resta uguale","quadruplica","diventa 16 volte maggiore"],a:3,s:"A = πr²: raggio metà → sezione un quarto → velocità ×4 (continuità)."},
{t:"u3c",k:"m",q:"Nel tratto di una stenosi, rispetto al tratto sano a monte, la pressione laterale del sangue è (Bernoulli):",o:["minore, perché la velocità aumenta","maggiore, perché il vaso è più stretto","uguale","nulla","maggiore, perché la velocità diminuisce"],a:0,s:"p + ½ρv² costante: dove v cresce, p cala; la parete può essere schiacciata dall'esterno."},
{t:"u3c",k:"c",q:"Il sangue (ρ ≈ 1000 kg/m³) scorre a 0,5 m/s e in una stenosi accelera a 2 m/s. Per Bernoulli la pressione cala di ____ Pa.",a:["1875","1.875"],s:"Δp = ½ρ(v₂² − v₁²) = 500·(4 − 0,25) = 1875 Pa."},
{t:"u3c",k:"m",q:"Un aneurisma dell'aorta ha sezione tripla rispetto al tratto sano. Nel tratto dilatato il sangue:",o:["rallenta a un terzo e la pressione laterale aumenta","triplica la velocità e la pressione cala","rallenta a un nono e la pressione cala","mantiene la stessa velocità","rallenta a un terzo e la pressione cala"],a:0,s:"Continuità: v ∝ 1/A. Bernoulli: v minore → p maggiore, che sfianca ulteriormente la parete."},
{t:"u3c",k:"c",q:"Un tubo di sezione 4 cm² è percorso da acqua a 0,5 m/s: la portata è ____ cm³/s.",a:["200","DUECENTO"],s:"Q = A·v = 4 cm² · 50 cm/s = 200 cm³/s."},
{t:"u3c",k:"m",q:"Da un foro sul fianco di un serbatoio aperto, 5 m sotto il pelo libero, l'acqua esce con velocità (legge di Torricelli, g = 10 m/s²):",o:["5 m/s","50 m/s","100 m/s","√5 m/s","10 m/s"],a:4,s:"Bernoulli: v = √(2gh) = √100 = 10 m/s."},
{t:"u3d",k:"m",q:"Due vasi con resistenza idraulica R e 2R sono collegati in parallelo. La resistenza equivalente è:",o:["2R/3","R/3","3R","3R/2","2R"],a:0,s:"1/R_eq = 1/R + 1/(2R) = 3/(2R) → R_eq = 2R/3, minore della più piccola."},
{t:"u3d",k:"c",q:"Quattro capillari identici, ciascuno con resistenza idraulica R, collegati in parallelo hanno resistenza totale R/____.",a:["4","QUATTRO"],s:"n resistenze uguali in parallelo: R/n."},
{t:"u3d",k:"m",q:"Un vaso ha resistenza idraulica 2·10⁸ Pa·s/m³ e ai suoi capi c'è una differenza di pressione di 4000 Pa. La portata è:",o:["2·10⁻⁵ m³/s","8·10¹¹ m³/s","5·10⁴ m³/s","2·10⁻⁴ m³/s","5·10⁻⁶ m³/s"],a:0,s:"Q = Δp/R = 4·10³ / 2·10⁸ = 2·10⁻⁵ m³/s (20 mL/s)."},
{t:"u3d",k:"m",q:"Nel circolo sistemico la caduta di pressione maggiore avviene a livello di:",o:["aorta","grandi vene","atrio destro","vena cava","arteriole"],a:4,s:"Le arteriole hanno raggio piccolo (R ∝ 1/r⁴) e non sono abbastanza numerose in parallelo da compensarlo, come invece accade ai capillari."},
{t:"u3d",k:"c",q:"Nel moto laminare in un tubo il gradiente di velocità (differenza di velocità tra strati vicini) è massimo vicino alle ____ del tubo.",a:["PARETI","PARETE"],s:"Nel profilo parabolico la velocità è massima al centro, dove la curva è piatta, e varia più rapidamente vicino alle pareti."},
{t:"u3e",k:"m",q:"Per la legge di Laplace in un vaso cilindrico (tensione di parete T = p·r), a parità di pressione interna la tensione nella parete:",o:["è maggiore nei vasi di raggio maggiore","è maggiore nei capillari","non dipende dal raggio","è nulla nelle arterie","diminuisce aumentando la pressione"],a:0,s:"T cresce con r: per questo un aneurisma, dilatandosi, è sottoposto a tensione sempre maggiore, mentre i capillari reggono con pareti sottilissime."},
{t:"u3e",k:"m",q:"Due alveoli con la stessa tensione superficiale sono collegati; uno ha raggio metà dell'altro. Senza surfattante:",o:["l'aria va dal grande al piccolo","l'aria va dal piccolo al grande, che si gonfia","non c'è passaggio d'aria","entrambi si svuotano verso l'esterno","la pressione è uguale nei due"],a:1,s:"Δp = 2τ/r è maggiore nell'alveolo piccolo, che si svuota in quello grande."},
{t:"u3e",k:"c",q:"Una bollicina di gas nel sangue (τ ≈ 0,05 N/m) ha raggio 0,1 mm: la pressione interna supera quella esterna di ____ Pa (Δp = 2τ/r).",a:["1000","1.000","MILLE"],s:"Δp = 2·0,05 / 10⁻⁴ = 1000 Pa."},
{t:"u3e",k:"m",q:"Nei neonati prematuri la sindrome da distress respiratorio è dovuta a carenza di surfattante. In termini fisici:",o:["la pressione atmosferica negli alveoli diminuisce","la viscosità dell'aria aumenta","gli alveoli diventano rigidi come capillari di vetro","la tensione superficiale resta alta e gli alveoli piccoli tendono a collassare","la capillarità fa salire il sangue nei bronchi"],a:3,s:"Senza surfattante τ è alta e, per Laplace, gli alveoli più piccoli hanno pressione maggiore e si svuotano (atelettasia)."},
{t:"u3e",k:"c",q:"Un liquido che bagna il vetro, come l'acqua, forma in un capillare un menisco ____ (concavo/convesso).",a:["CONCAVO"],s:"Adesione maggiore della coesione: il liquido risale lungo le pareti. Il mercurio forma un menisco convesso."},
{t:"u3e",k:"m",q:"L'acqua sale di 3 cm in un capillare di vetro. In un capillare dello stesso vetro ma con raggio triplo salirebbe di:",o:["9 cm","27 cm","3 cm","0,33 cm","1 cm"],a:4,s:"h ∝ 1/r: raggio ×3 → altezza ÷3 = 1 cm."},

/* ---------- U4 · Onde meccaniche ---------- */
{t:"u4a",k:"m",q:"Un'onda è descritta da y(x,t) = 0,02·sin(2x − 10t), in unità SI. La sua velocità di propagazione è:",o:["20 m/s","0,2 m/s","10 m/s","5 m/s","0,02 m/s"],a:3,s:"k = 2 rad/m e ω = 10 rad/s: v = ω/k = 5 m/s."},
{t:"u4a",k:"c",q:"Un'onda ha frequenza 50 Hz: la sua pulsazione è ω = ____ π rad/s (scrivi il coefficiente di π).",a:["100","CENTO"],s:"ω = 2πf = 100π rad/s."},
{t:"u4a",k:"m",q:"Nell'equazione dell'onda armonica y = A·sin(kx − ωt) il numero d'onda k è uguale a 2π diviso:",o:["il periodo","la frequenza","la velocità","l'ampiezza","la lunghezza d'onda"],a:4,s:"k = 2π/λ, come ω = 2π/T per il tempo."},
{t:"u4b",k:"m",q:"A 3 m da una sorgente sonora puntiforme l'intensità è 9·10⁻⁴ W/m². A 9 m vale:",o:["10⁻⁴ W/m²","3·10⁻⁴ W/m²","10⁻³ W/m²","8,1·10⁻³ W/m²","10⁻⁵ W/m²"],a:0,s:"Distanza ×3 → intensità ÷9 (inverso del quadrato)."},
{t:"u4b",k:"c",q:"Una sorgente puntiforme emette in modo uniforme una potenza di 4π W: a 1 m di distanza l'intensità è ____ W/m².",a:["1","UNO"],s:"I = P/(4πr²) = 4π/(4π·1) = 1 W/m²."},
{t:"u4b",k:"m",q:"Passando da 1 m a 10 m da una sorgente puntiforme, il livello sonoro:",o:["diminuisce di 10 dB","si riduce a un decimo","diminuisce di 100 dB","diminuisce di 20 dB","resta invariato"],a:3,s:"Intensità ÷100 (inverso del quadrato) → −20 dB."},
{t:"u4c",k:"m",q:"Un osservatore corre verso una sorgente sonora ferma. Rispetto alla frequenza emessa, quella che percepisce è:",o:["minore","uguale","maggiore","nulla","dipende solo dall'intensità"],a:2,s:"Andando incontro all'onda incontra più creste al secondo."},
{t:"u4c",k:"c",q:"In ecografia un'eco ritorna alla sonda dopo 100 µs; con v = 1540 m/s nei tessuti, l'interfaccia è a circa ____ cm di profondità.",a:["7,7","7.7","7,70","7.70"],s:"d = v·t/2 = 1540·10⁻⁴/2 = 0,077 m (andata e ritorno)."},
{t:"u4c",k:"m",q:"Nell'istante in cui un'ambulanza passa davanti a un pedone, muovendosi perpendicolarmente alla linea che li unisce, la frequenza percepita:",o:["è massima","è uguale a quella emessa","è minima","è nulla","è doppia di quella emessa"],a:1,s:"Conta solo la componente della velocità lungo la congiungente, che in quell'istante è nulla."},
{t:"u4c",k:"m",q:"Un'ambulanza emette 1000 Hz e si allontana a 34 m/s (suono a 340 m/s). La frequenza percepita è circa:",o:["1100 Hz","1000 Hz","34 Hz","1110 Hz","910 Hz"],a:4,s:"Si allontana: frequenza minore, circa il 10% in meno (f' = 1000·340/374 ≈ 909 Hz)."},
{t:"u4c",k:"c",q:"Nell'ecodoppler lo spostamento di frequenza dell'eco è proporzionale alla ____ del sangue (una parola).",a:["VELOCITÀ","VELOCITA"],s:"Δf/f ≈ 2v/v_suono: dallo spostamento si ricava la velocità del flusso."},
{t:"u4c",k:"m",q:"Una sonda ecografica da 1,5 MHz lavora in un tessuto in cui il suono viaggia a 1500 m/s. La lunghezza d'onda è:",o:["1 mm","1 m","1 cm","0,1 mm","1 µm"],a:0,s:"λ = v/f = 1500/1,5·10⁶ = 10⁻³ m: frequenze più alte danno dettagli più fini."},
{t:"u4d",k:"m",q:"Due altoparlanti in fase emettono onde con λ = 0,5 m. In un punto la differenza dei cammini è 1,5 m. Lì l'interferenza è:",o:["distruttiva","costruttiva solo per metà del tempo","sempre nulla","impossibile da stabilire","costruttiva"],a:4,s:"1,5 m = 3λ, multiplo intero: le onde arrivano in fase."},
{t:"u4d",k:"c",q:"Due onde in fase con λ = 40 cm: la più piccola differenza di cammino che dà interferenza distruttiva è ____ cm.",a:["20","VENTI"],s:"Distruttiva per λ/2, 3λ/2…: la minima è λ/2 = 20 cm."},
{t:"u4d",k:"m",q:"Due onde della stessa frequenza, di ampiezza 3 e 5, si sovrappongono in opposizione di fase. L'ampiezza risultante è:",o:["8","0","4","15","2"],a:4,s:"In opposizione di fase le ampiezze si sottraggono: 5 − 3 = 2."},
{t:"u4d",k:"m",q:"In un oscillatore massa-molla, nel punto di massimo allungamento:",o:["velocità nulla e accelerazione massima","velocità e accelerazione nulle","velocità massima e accelerazione nulla","velocità e accelerazione massime","energia cinetica massima"],a:0,s:"Agli estremi la massa si ferma e la forza elastica −kx è massima."},
{t:"u4d",k:"c",q:"Un oscillatore compie 10 oscillazioni complete in 5 s: la sua frequenza è ____ Hz.",a:["2","DUE"],s:"f = 10/5 = 2 Hz; periodo 0,5 s."},

/* ---------- U5 · Termodinamica ---------- */
{t:"u5a",k:"m",q:"Quanto calore serve per fondere 2 kg di ghiaccio già a 0 °C? (calore latente di fusione 334 kJ/kg)",o:["167 kJ","334 kJ","8,4 kJ","2,7 MJ","668 kJ"],a:4,s:"Q = λ·m = 334·2 = 668 kJ; la temperatura resta 0 °C."},
{t:"u5a",k:"c",q:"Una temperatura di 100 °C corrisponde a ____ °F.",a:["212"],s:"°F = 1,8·100 + 32 = 212."},
{t:"u5a",k:"m",q:"Una massa di ferro (c ≈ 450 J/(kg·K)) e una uguale massa d'acqua (c ≈ 4200 J/(kg·K)) ricevono lo stesso calore. L'aumento di temperatura del ferro, rispetto all'acqua, è:",o:["circa 9 volte minore","uguale","circa 9 volte maggiore","doppio","nullo"],a:2,s:"ΔT = Q/(c·m): c circa 9 volte minore → ΔT circa 9 volte maggiore."},
{t:"u5a",k:"c",q:"Si mescolano, senza perdite, 1 kg d'acqua a 80 °C e 4 kg d'acqua a 20 °C: la temperatura finale è ____ °C.",a:["32"],s:"Media pesata: (1·80 + 4·20)/5 = 160/5 = 32 °C."},
{t:"u5a",k:"m",q:"La capacità termica di 3 kg d'acqua (c = 4,2 kJ/(kg·K)) è:",o:["12,6 kJ/K","4,2 kJ/K","1,4 kJ/K","12,6 kJ","4,2 kJ/(kg·K)"],a:0,s:"C = c·m = 12,6 kJ/K: è riferita all'intero corpo, non al kg."},
{t:"u5b",k:"m",q:"Per scaldare di 1 K una mole di gas perfetto monoatomico a volume costante servono circa (R ≈ 8,3 J/(mol·K)):",o:["8,3 J","20,8 J","4,2 J","12,5 J","25 J"],a:3,s:"c_v = (3/2)R ≈ 12,5 J/(mol·K); 20,8 J sarebbe a pressione costante, (5/2)R."},
{t:"u5b",k:"m",q:"Per scaldare di ΔT la stessa quantità di gas perfetto serve più calore a pressione costante che a volume costante perché:",o:["a pressione costante il gas, espandendosi, compie anche lavoro","a pressione costante l'energia interna non cambia","a volume costante il gas cede calore","a volume costante si compie più lavoro","le temperature in kelvin sono diverse"],a:0,s:"Q_p = ΔU + pΔV, mentre a volume costante Q_v = ΔU: lo stesso ΔT dà lo stesso ΔU."},
{t:"u5b",k:"c",q:"Per un gas perfetto vale la relazione di Mayer: c_p − c_v = ____ (una lettera).",a:["R"],s:"Calori specifici molari: la differenza è la costante dei gas."},
{t:"u5b",k:"c",q:"2 moli di gas perfetto a 300 K occupano 0,05 m³ (R ≈ 8,3 J/(mol·K)): la pressione è circa ____ kPa.",a:["100","99,6","99.6","CENTO"],s:"p = nRT/V = 2·8,3·300/0,05 ≈ 99 600 Pa ≈ 100 kPa, circa 1 atm."},
{t:"u5c",k:"m",q:"Un gas viene compresso rapidamente, senza scambi di calore (adiabatica). La sua temperatura:",o:["diminuisce","resta costante","dipende solo dalla pressione esterna","si annulla","aumenta"],a:4,s:"Q = 0 e il lavoro fatto sul gas aumenta l'energia interna: ΔU = −L > 0 (come la pompa della bici che si scalda)."},
{t:"u5c",k:"c",q:"Un gas riceve 300 J di calore e intanto l'ambiente compie su di esso un lavoro di 100 J: la sua energia interna aumenta di ____ J.",a:["400"],s:"ΔU = Q − L con L = −100 J (lavoro subito): 300 + 100 = 400 J."},
{t:"u5d",k:"m",q:"Secondo l'interpretazione statistica di Boltzmann, l'entropia di un sistema:",o:["è proporzionale al logaritmo del numero di microstati","è proporzionale alla temperatura","diminuisce all'aumentare dei microstati","è sempre nulla per i gas","dipende dal percorso seguito"],a:0,s:"S = k·ln W, con W numero di microstati compatibili con lo stato macroscopico."},
{t:"u5d",k:"m",q:"Una goccia d'inchiostro si diffonde in un bicchiere d'acqua e non torna mai a raccogliersi da sola. Il motivo è che:",o:["l'energia non si conserverebbe","lo stato mescolato corrisponde a un numero enormemente maggiore di microstati","l'inchiostro è più denso dell'acqua","lo vieta il primo principio","la temperatura dell'acqua scenderebbe sotto zero"],a:1,s:"Il ritorno spontaneo non viola l'energia, ma è enormemente improbabile: i processi vanno verso l'entropia maggiore."},
{t:"u5d",k:"c",q:"Una macchina termica assorbe 800 J dalla sorgente calda e compie 200 J di lavoro per ciclo: il rendimento è ____ (in decimale).",a:["0,25","0.25","25%"],s:"η = L/Q_c = 200/800 = 0,25."},
{t:"u5d",k:"m",q:"Una macchina di Carnot lavora tra 127 °C e 27 °C. Il suo rendimento è:",o:["79%","21%","75%","100%","25%"],a:4,s:"In kelvin: 400 K e 300 K → η = 1 − 300/400 = 25% (79% viene usando i gradi Celsius)."},
{t:"u5d",k:"c",q:"Un corpo a 300 K assorbe in modo reversibile 600 J di calore a temperatura costante: la sua entropia aumenta di ____ J/K.",a:["2","DUE"],s:"ΔS = Q/T = 600/300 = 2 J/K."},
{t:"u5e",k:"m",q:"Se la temperatura assoluta di un corpo raddoppia, la potenza che emette per irraggiamento:",o:["raddoppia","quadruplica","aumenta di 8 volte","aumenta di 16 volte","resta uguale"],a:3,s:"P ∝ T⁴: 2⁴ = 16."},
{t:"u5e",k:"c",q:"La potenza trasmessa per conduzione attraverso una parete è proporzionale all'area e alla differenza di temperatura, e inversamente proporzionale allo ____ della parete.",a:["SPESSORE"],s:"Q/t = k·A·ΔT/d."},
{t:"u5e",k:"m",q:"Il sangue che porta il calore dagli organi interni alla pelle è un esempio di:",o:["conduzione","irraggiamento","evaporazione","convezione","sublimazione"],a:3,s:"Il calore viaggia con un fluido in movimento."},
{t:"u5e",k:"m",q:"Una parete di 10 m², spessa 20 cm (k = 0,5 W/(m·K)), separa 20 °C da 0 °C. La potenza dispersa per conduzione è:",o:["5 W","50 W","20 W","5000 W","500 W"],a:4,s:"P = k·A·ΔT/d = 0,5·10·20/0,2 = 500 W."},
{t:"u5e",k:"c",q:"In un ambiente a 40 °C, più caldo della pelle, il corpo riesce a disperdere calore quasi solo per ____ del sudore.",a:["EVAPORAZIONE"],s:"Conduzione, convezione e irraggiamento portano calore verso il corpo; l'evaporazione sottrae calore latente."},
{t:"u5e",k:"m",q:"Un thermos ha doppia parete con il vuoto in mezzo e superfici a specchio. Che cosa riducono il vuoto e lo specchio?",o:["il vuoto l'irraggiamento, lo specchio la conduzione","entrambi solo la conduzione","entrambi solo la convezione","entrambi l'evaporazione","il vuoto conduzione e convezione, lo specchio l'irraggiamento"],a:4,s:"Senza materia non c'è conduzione né convezione; la superficie riflettente rimanda indietro l'infrarosso."},

/* ---------- U6 · Elettricità e magnetismo ---------- */
{t:"u6a",k:"m",q:"Una bacchetta carica attira piccoli pezzi di carta scarichi. Il fenomeno è dovuto a:",o:["polarizzazione delle molecole della carta","induzione, con elettroni liberi che percorrono la carta","trasferimento di carica a distanza","magnetismo","forza gravitazionale"],a:0,s:"La carta è un isolante: le molecole si orientano, la parte vicina ha carica opposta a quella della bacchetta ed è più vicina, quindi prevale l'attrazione."},
{t:"u6a",k:"m",q:"Si avvicina una bacchetta positiva a una sfera metallica isolata, si collega la sfera a terra, si stacca il collegamento e infine si allontana la bacchetta. La sfera resta carica:",o:["positivamente","non resta carica","in modo che dipende dal materiale della bacchetta","positivamente e negativamente in parti uguali","negativamente"],a:4,s:"Carica per induzione: dalla terra salgono elettroni attratti dalla bacchetta e restano intrappolati quando si stacca il filo."},
{t:"u6a",k:"c",q:"Due cariche di 1 µC ciascuna, a 1 m di distanza, si respingono con una forza di ____ ·10⁻³ N (k = 9·10⁹ N·m²/C²).",a:["9","NOVE"],s:"F = 9·10⁹·10⁻⁶·10⁻⁶ / 1 = 9·10⁻³ N."},
{t:"u6a",k:"m",q:"In un materiale dielettrico immerso in un campo elettrico:",o:["le cariche si spostano liberamente fino alla superficie","il campo interno diventa nullo","le molecole si polarizzano e il campo interno si riduce","si genera una corrente continua","il campo interno aumenta"],a:2,s:"Polarizzazione: i dipoli orientati creano un campo opposto che indebolisce quello esterno (fattore εᵣ)."},
{t:"u6a",k:"c",q:"Un corpo che ha perso 10¹³ elettroni ha una carica di ____ µC (e = 1,6·10⁻¹⁹ C).",a:["1,6","1.6","+1,6","+1.6"],s:"Q = 10¹³·1,6·10⁻¹⁹ = 1,6·10⁻⁶ C, positiva."},
{t:"u6b",k:"m",q:"Un elettrone entra con velocità orizzontale tra le armature di un condensatore piano, dove il campo è uniforme e verticale. La sua traiettoria è:",o:["rettilinea","circolare","a spirale","elicoidale","parabolica"],a:4,s:"Forza costante perpendicolare alla velocità iniziale: come un sasso lanciato in orizzontale."},
{t:"u6b",k:"m",q:"Un protone (q = 1,6·10⁻¹⁹ C, m ≈ 1,6·10⁻²⁷ kg) si trova in un campo elettrico uniforme di 10³ V/m. La sua accelerazione è circa:",o:["10¹¹ m/s²","10⁻¹¹ m/s²","10⁸ m/s²","1,6·10⁻¹⁶ m/s²","10¹⁴ m/s²"],a:0,s:"a = qE/m = 1,6·10⁻¹⁶ / 1,6·10⁻²⁷ = 10¹¹ m/s² (1,6·10⁻¹⁶ è la forza in newton)."},
{t:"u6b",k:"c",q:"Una carica di 2 µC passa da un punto a potenziale 50 V a uno a potenziale 10 V: il campo compie un lavoro di ____ ·10⁻⁵ J.",a:["8","OTTO"],s:"L = q·(V_A − V_B) = 2·10⁻⁶·40 = 8·10⁻⁵ J."},
{t:"u6b",k:"m",q:"Un elettrone viene lasciato libero, da fermo, in un campo elettrico uniforme. Si muove:",o:["nel verso del campo, di moto uniforme","nel verso del campo, di moto uniformemente accelerato","lungo una circonferenza","in verso opposto al campo, di moto uniformemente accelerato","restando fermo"],a:3,s:"Carica negativa: F = qE è opposta a E; forza costante → accelerazione costante."},
{t:"u6c",k:"m",q:"Due condensatori da 6 µF collegati in serie equivalgono a:",o:["3 µF","6 µF","12 µF","36 µF","1,5 µF"],a:0,s:"1/C = 1/6 + 1/6 → C = 3 µF (al contrario delle resistenze)."},
{t:"u6c",k:"c",q:"Tre condensatori da 2 µF, 3 µF e 5 µF collegati in parallelo equivalgono a ____ µF.",a:["10","DIECI"],s:"In parallelo le capacità si sommano."},
{t:"u6c",k:"m",q:"Due condensatori diversi collegati in serie a una pila hanno sempre uguale:",o:["carica","tensione","capacità","energia","area delle armature"],a:0,s:"In serie la stessa carica Q si trova su ogni condensatore; la tensione si divide (V = Q/C)."},
{t:"u6c",k:"c",q:"Un condensatore piano ha capacità 5 pF nel vuoto; riempito con un dielettrico di εᵣ = 4 la capacità diventa ____ pF.",a:["20","VENTI"],s:"C = εᵣ·C₀ = 4·5 = 20 pF."},
{t:"u6c",k:"m",q:"Un condensatore da 3 µF in serie con uno da 6 µF; il gruppo è in parallelo con un condensatore da 4 µF. La capacità equivalente è:",o:["13 µF","6 µF","2 µF","1,33 µF","10 µF"],a:1,s:"Serie: 3·6/(3 + 6) = 2 µF; in parallelo con 4 µF: 6 µF."},
{t:"u6c",k:"m",q:"Raddoppiando la tensione a cui è caricato un condensatore, l'energia immagazzinata:",o:["raddoppia","si dimezza","resta uguale","quadruplica","aumenta di 8 volte"],a:3,s:"U = ½CV²: dipende dal quadrato della tensione."},
{t:"u6d",k:"m",q:"Un filo di rame lungo 10 m con sezione 1 mm² (ρ ≈ 1,7·10⁻⁸ Ω·m) ha resistenza:",o:["0,17 Ω","1,7 Ω","17 Ω","1,7·10⁻⁷ Ω","0,017 Ω"],a:0,s:"R = ρl/A = 1,7·10⁻⁸·10/10⁻⁶ = 0,17 Ω (1 mm² = 10⁻⁶ m²)."},
{t:"u6d",k:"c",q:"Una stufa elettrica da 2 kW resta accesa 3 ore: consuma ____ kWh.",a:["6","SEI"],s:"E = P·t = 2 kW · 3 h = 6 kWh."},
{t:"u6d",k:"m",q:"Due resistenze da 3 Ω e 6 Ω in parallelo sono collegate a un generatore ideale da 12 V. La corrente erogata dal generatore è:",o:["1,33 A","2 A","9 A","4 A","6 A"],a:4,s:"R_eq = 3·6/9 = 2 Ω; I = 12/2 = 6 A (1,33 A è il risultato con le resistenze in serie)."},
{t:"u6d",k:"m",q:"Due lampadine identiche sono collegate alla stessa pila prima in serie e poi in parallelo. La potenza totale in parallelo, rispetto a quella in serie, è:",o:["uguale","doppia","la metà","un quarto","4 volte maggiore"],a:4,s:"P = V²/R_eq: in serie R_eq = 2R, in parallelo R/2, rapporto 4."},
{t:"u6e",k:"m",q:"Per una carica in un campo magnetico uniforme (v perpendicolare a B) il raggio della traiettoria è r = mv/(qB). Raddoppiando la velocità il raggio:",o:["si dimezza","diventa infinito","quadruplica","resta uguale","raddoppia"],a:4,s:"r è proporzionale a v."},
{t:"u6e",k:"c",q:"Un protone (m ≈ 1,6·10⁻²⁷ kg, q = 1,6·10⁻¹⁹ C) a 10⁵ m/s entra perpendicolarmente in un campo di 0,01 T: il raggio della traiettoria è ____ m.",a:["0,1","0.1","0,10","0.10"],s:"r = mv/(qB) = 1,6·10⁻²² / 1,6·10⁻²¹ = 0,1 m."},
{t:"u6e",k:"m",q:"Nell'esperimento di Oersted l'ago di una bussola posta vicino a un filo rettilineo percorso da corrente si dispone:",o:["parallelo al filo","sempre verso il nord geografico","in direzione radiale, puntando verso il filo","perpendicolare al filo, tangente a circonferenze centrate sul filo","in modo casuale"],a:3,s:"Le linee del campo di un filo sono circonferenze concentriche attorno al filo (regola della mano destra)."},
{t:"u6e",k:"m",q:"Si avvicina il polo nord di un magnete a una spira. Per la legge di Lenz, la corrente indotta nella spira:",o:["crea un polo nord rivolto verso il magnete, che lo respinge","crea un polo sud rivolto verso il magnete, che lo attira","è nulla","ha un verso che non dipende dal moto","rafforza l'aumento di flusso"],a:0,s:"La corrente indotta si oppone alla causa: si oppone all'avvicinamento, quindi respinge il magnete."},
{t:"u6e",k:"c",q:"Il flusso magnetico attraverso una bobina passa da 0,5 Wb a 0,1 Wb in 0,2 s: la f.e.m. indotta media ha modulo ____ V.",a:["2","DUE"],s:"|ΔΦ/Δt| = 0,4/0,2 = 2 V."},

/* ---------- U7 · Fisica delle radiazioni ---------- */
{t:"u7a",k:"m",q:"Una radiazione elettromagnetica è ionizzante quando:",o:["l'energia di ogni singolo fotone supera l'energia di legame degli elettroni (circa 10 eV)","la sua intensità è molto alta","ha una lunghezza d'onda grande","è prodotta da un'antenna","si propaga nel vuoto"],a:0,s:"Conta l'energia del singolo fotone, E = hf, non quanti fotoni ci sono: un fascio intenso di microonde non ionizza."},
{t:"u7a",k:"c",q:"Un fotone di lunghezza d'onda 124 nm ha energia ____ eV (hc ≈ 1240 eV·nm).",a:["10","DIECI"],s:"E = hc/λ = 1240/124 = 10 eV: ultravioletto, al limite della ionizzazione."},
{t:"u7a",k:"m",q:"Quale di questi esami usa radiazioni ionizzanti?",o:["ecografia","risonanza magnetica","TAC","elettrocardiogramma","termografia a infrarossi"],a:2,s:"La TAC usa raggi X; la risonanza usa onde radio, l'ecografia ultrasuoni (onde meccaniche)."},
{t:"u7b",k:"c",q:"Luce di lunghezza d'onda 600 nm nel vuoto entra in un vetro con n = 1,5: nel vetro la lunghezza d'onda è ____ nm.",a:["400"],s:"La frequenza resta uguale, la velocità diventa c/n: λ' = λ/n = 400 nm."},
{t:"u7b",k:"m",q:"Un raggio passa dall'aria (n = 1) a un vetro con n = √3, con angolo di incidenza di 60°. L'angolo di rifrazione è:",o:["60°","45°","90°","30°","0°"],a:3,s:"sin r = sin 60°/√3 = (√3/2)/√3 = 0,5 → r = 30°."},
{t:"u7b",k:"m",q:"Uno specchio piano riceve un raggio inclinato di 35° rispetto alla normale. L'angolo tra il raggio incidente e quello riflesso è:",o:["35°","55°","110°","90°","70°"],a:4,s:"Angolo di riflessione = angolo di incidenza: tra i due raggi 35° + 35° = 70°."},
{t:"u7c",k:"c",q:"Un oggetto è a 15 cm da una lente convergente con f = 10 cm: l'immagine si forma a ____ cm dalla lente.",a:["30","TRENTA"],s:"1/q = 1/10 − 1/15 = 1/30 → q = 30 cm."},
{t:"u7c",k:"m",q:"Un oggetto alto 1 cm è a 15 cm da una lente convergente con f = 10 cm. L'immagine è:",o:["alta 2 cm, reale e capovolta","alta 0,5 cm, reale e capovolta","alta 2 cm, virtuale e diritta","alta 3 cm, reale e diritta","alta 1 cm, virtuale"],a:0,s:"q = 30 cm, ingrandimento m = −q/p = −2: doppia e capovolta, reale."},
{t:"u7c",k:"m",q:"Un oggetto è a 5 cm da una lente convergente con f = 10 cm. L'immagine si trova:",o:["a 10 cm dalla parte opposta, reale","a 3,3 cm, reale","all'infinito","a 10 cm dalla stessa parte dell'oggetto, virtuale e ingrandita 2 volte","a 5 cm, virtuale e rimpicciolita"],a:3,s:"1/q = 1/10 − 1/5 = −1/10 → q = −10 cm (virtuale); m = −q/p = +2."},
{t:"u7c",k:"c",q:"L'ingrandimento lineare di una lente è m = −q/p: un oggetto a 40 cm che dà un'immagine reale a 10 cm ha ingrandimento, in modulo, ____.",a:["0,25","0.25","1/4"],s:"|m| = 10/40 = 0,25: immagine quattro volte più piccola."},
{t:"u7c",k:"m",q:"Una lente convergente forma un'immagine reale alla stessa distanza dell'oggetto, 40 cm. La distanza focale è:",o:["20 cm","80 cm","40 cm","10 cm","−20 cm"],a:0,s:"p = q = 2f → 1/f = 2/40 → f = 20 cm."},
{t:"u7c",k:"m",q:"Due lenti sottili accostate, da +3 D e +2 D, hanno complessivamente un potere diottrico di:",o:["+1 D","+6 D","+1,2 D","+5 D","+1,5 D"],a:3,s:"Per lenti sottili a contatto i poteri diottrici si sommano."},
{t:"u7d",k:"m",q:"Una soluzione ha assorbanza 0,3. Ricordando che 10^0,3 ≈ 2, la frazione di luce trasmessa è circa:",o:["30%","70%","0,3%","3%","50%"],a:4,s:"T = 10^(−0,3) ≈ 1/2."},
{t:"u7d",k:"c",q:"Una soluzione trasmette l'1% della luce incidente: la sua assorbanza è ____.",a:["2","DUE"],s:"A = log₁₀(I₀/I) = log₁₀ 100 = 2."},
{t:"u7d",k:"m",q:"Una soluzione 0,1 mol/L in una cuvetta di 1 cm ha assorbanza 0,6. Il coefficiente di assorbimento molare ε è:",o:["0,06 L/(mol·cm)","60 L/(mol·cm)","0,6 L/(mol·cm)","16,7 L/(mol·cm)","6 L/(mol·cm)"],a:4,s:"ε = A/(c·l) = 0,6/(0,1·1) = 6 L/(mol·cm)."},
{t:"u7d",k:"m",q:"Secondo la legge di Lambert-Beer, quale di questi grafici è una retta passante per l'origine?",o:["intensità trasmessa in funzione della concentrazione","assorbanza in funzione della concentrazione","trasmittanza in funzione dello spessore","intensità trasmessa in funzione dello spessore","trasmittanza in funzione della concentrazione"],a:1,s:"A = εcl è proporzionale a c; intensità e trasmittanza calano invece in modo esponenziale."},
{t:"u7d",k:"c",q:"Ogni centimetro di un materiale dimezza l'intensità di un fascio: dopo 3 cm l'intensità trasmessa è 1/____ di quella iniziale.",a:["8","OTTO"],s:"½·½·½ = 1/8: l'attenuazione è esponenziale, non lineare."},
{t:"u7d",k:"m",q:"Lo spessore emivalente di un materiale (quello che dimezza l'intensità di un fascio X) è 2 mm. Per ridurre l'intensità al 25% servono:",o:["1 mm","8 mm","6 mm","4 mm","50 mm"],a:3,s:"25% = ½·½: due spessori emivalenti, 4 mm."},
{t:"u7d",k:"m",q:"Una soluzione ha assorbanza 0,8 in una cuvetta da 1 cm. Diluendola a metà concentrazione e misurandola in una cuvetta da 2 cm, l'assorbanza diventa:",o:["0,4","1,6","0,2","3,2","0,8"],a:4,s:"A = εcl: c dimezzata e l raddoppiato, il prodotto non cambia."},
{t:"u7e",k:"c",q:"Un radiofarmaco con emivita di 6 ore viene somministrato con un'attività di 640 MBq: dopo 18 ore l'attività è ____ MBq.",a:["80","OTTANTA"],s:"18 h = 3 emivite: 640/8 = 80 MBq."},
{t:"u7e",k:"m",q:"Nel decadimento γ, il numero di massa A e il numero atomico Z del nucleo:",o:["diminuiscono entrambi","Z aumenta di 1","restano invariati","A diminuisce di 4, Z di 2","A aumenta di 1"],a:2,s:"Si emette solo un fotone: il nucleo passa da uno stato eccitato a uno meno energetico."},
{t:"u7e",k:"m",q:"Lo iodio-131 (Z = 53) decade β⁻. Il nucleo figlio ha:",o:["Z = 52, A = 131","Z = 51, A = 127","Z = 53, A = 130","Z = 54, A = 132","Z = 54, A = 131"],a:4,s:"β⁻: un neutrone diventa protone, Z + 1 e A invariato (si forma xeno-131)."},
{t:"u7e",k:"m",q:"Il grafico del numero di nuclei radioattivi non ancora decaduti in funzione del tempo è:",o:["una retta decrescente","una retta orizzontale","una parabola","una retta crescente","un'esponenziale decrescente"],a:4,s:"N(t) = N₀·e^(−λt): in ogni emivita si dimezza ciò che resta, quindi la curva non tocca mai lo zero."}
);

/* ---------- Test d'ingresso: 2 domande nuove per unità (livello scuola superiore) ---------- */
FIS_PT.push(
P("u1","u1a","Quale di queste è l'unità di misura della massa nel Sistema Internazionale?",["newton","chilogrammo","litro","joule","metro"],1,"Il chilogrammo (kg) è una delle sette unità fondamentali.",["Il newton misura una forza, per esempio il peso.","","Il litro misura un volume.","Il joule misura l'energia.","Il metro misura una lunghezza."]),
P("u1","u1b","Come si scrive 0,004 in notazione scientifica?",["4·10³","4·10⁻²","4·10⁴","4·10⁻³","4·10⁻⁴"],3,"La virgola si sposta di 3 posti verso destra: 4·10⁻³.",["Esponente positivo: sarebbe 4000.","Hai contato due posti invece di tre: sarebbe 0,04.","Sarebbe 40 000.","","Hai contato quattro posti: sarebbe 0,0004."]),
P("u2","u2a","Un corridore percorre 100 m in 10 s a velocità costante. La sua velocità è:",["10 m/s","0,1 m/s","1000 m/s","10 km/h","100 m/s"],0,"v = s/t = 100/10 = 10 m/s.",["","Hai diviso il tempo per lo spazio.","Hai moltiplicato spazio e tempo.","Il numero è giusto ma l'unità no: 10 m/s sono 36 km/h.","È lo spazio, non la velocità."]),
P("u2","u2d","Un corpo di 1 kg si trova a 2 m di altezza (g ≈ 10 m/s²). La sua energia potenziale gravitazionale rispetto al suolo è:",["2 J","5 J","200 J","12 J","20 J"],4,"U = m·g·h = 1·10·2 = 20 J.",["Hai dimenticato g.","Hai diviso g per l'altezza.","Hai moltiplicato per 100.","Hai sommato g e h.",""]),
P("u3","u3b","Un oggetto galleggia sull'acqua. La sua densità media è:",["maggiore di quella dell'acqua","uguale a zero","minore di quella dell'acqua","esattamente uguale a quella dell'acqua","indipendente dal materiale"],2,"Galleggia chi è, in media, meno denso del liquido (principio di Archimede).",["Un corpo più denso dell'acqua affonda.","Ogni corpo con massa ha densità maggiore di zero.","","Con densità uguale resterebbe sospeso sott'acqua, senza emergere.","La densità dipende proprio dal materiale."]),
P("u3","u3c","Se si stringe con il dito l'uscita di un tubo da giardino, l'acqua esce:",["più lenta","con la stessa velocità","solo a gocce","non esce più","più veloce"],4,"La stessa portata passa da una sezione più piccola: la velocità aumenta (Q = A·v).",["È il contrario: sezione minore, velocità maggiore.","La velocità cambia perché cambia la sezione.","La portata resta la stessa, l'acqua non si blocca.","Il rubinetto continua a spingere la stessa portata.",""]),
P("u4","u4b","Il livello di intensità sonora si misura in:",["hertz","decibel","watt","pascal","metri"],1,"Il decibel (dB) è una scala logaritmica dell'intensità.",["L'hertz misura la frequenza, cioè l'altezza del suono.","","Il watt misura la potenza della sorgente.","Il pascal misura la pressione.","Il metro misura la lunghezza d'onda."]),
P("u4","u4a","Il periodo di un'onda è 0,1 s. La sua frequenza è:",["0,1 Hz","1 Hz","10 Hz","100 Hz","0,01 Hz"],2,"f = 1/T = 1/0,1 = 10 Hz.",["Hai confuso frequenza e periodo.","Hai ignorato il valore del periodo.","","Hai diviso per 0,01.","Hai moltiplicato invece di fare l'inverso."]),
P("u5","u5b","Se si scalda un palloncino chiuso, il suo volume:",["diminuisce","aumenta","resta uguale","si annulla","prima aumenta poi diminuisce"],1,"Il gas caldo spinge di più sulle pareti e il palloncino si gonfia (a pressione circa costante V ∝ T).",["Diminuisce raffreddandolo.","","Il gas si dilata con la temperatura.","Il gas non scompare.","Continua ad aumentare finché la temperatura sale."]),
P("u5","u5e","Il calore del Sole arriva sulla Terra attraverso lo spazio vuoto per:",["conduzione","convezione","evaporazione","irraggiamento","attrito"],3,"Le onde elettromagnetiche viaggiano anche nel vuoto.",["La conduzione richiede materia a contatto.","La convezione richiede un fluido in movimento.","L'evaporazione è un passaggio di stato.","","L'attrito non trasporta calore a distanza."]),
P("u6","u6d","Due resistenze da 10 Ω collegate in serie equivalgono a:",["5 Ω","10 Ω","100 Ω","0 Ω","20 Ω"],4,"In serie le resistenze si sommano: 10 + 10 = 20 Ω.",["Questo è il risultato in parallelo.","Hai considerato una sola resistenza.","Hai moltiplicato invece di sommare.","Una resistenza in più non può annullare il totale.",""]),
P("u6","u6e","L'ago di una bussola si orienta perché:",["è attratto dal Sole","è carico elettricamente","risente del campo magnetico terrestre","risente della gravità","è spinto dal vento"],2,"L'ago è un piccolo magnete che si allinea con il campo magnetico della Terra.",["Il Sole non c'entra.","L'ago è magnetizzato, non carico.","","La gravità agisce allo stesso modo in tutte le direzioni orizzontali.","La bussola funziona anche in una scatola chiusa."]),
P("u7","u7e","Il nucleo di un atomo contiene:",["protoni e neutroni","protoni ed elettroni","solo elettroni","solo neutroni","fotoni"],0,"Protoni (positivi) e neutroni (neutri); gli elettroni stanno attorno al nucleo.",["","Gli elettroni non stanno nel nucleo.","Gli elettroni stanno fuori dal nucleo.","Mancano i protoni, che danno il numero atomico.","I fotoni sono luce, non costituenti del nucleo."]),
P("u7","u7b","Una cannuccia immersa in un bicchiere d'acqua sembra spezzata. Il fenomeno si chiama:",["riflessione","diffrazione","interferenza","rifrazione","assorbimento"],3,"La luce cambia direzione passando dall'acqua all'aria.",["La riflessione è il rimbalzo su una superficie, come in uno specchio.","La diffrazione riguarda ostacoli e fenditure piccole.","L'interferenza è la sovrapposizione di onde.","","L'assorbimento attenua la luce, non la devia."])
);

/* ---------- Spiegazioni aggiuntive per le voci del syllabus meno coperte ---------- */
(function(){
const T=id=>FIS_TOPICS.find(t=>t.id===id);
T("u1a").sp.push("Grandezze scalari e vettoriali: una grandezza scalare è descritta completamente da un numero con la sua unità (massa, tempo, temperatura, energia, lavoro, pressione); una vettoriale ha bisogno anche di direzione e verso (spostamento, velocità, accelerazione, forza, quantità di moto, campo elettrico). Le scalari si sommano come numeri, le vettoriali con le regole dei vettori. Attenzione: la pressione è scalare anche se nasce da una forza, perché in un fluido agisce allo stesso modo in tutte le direzioni.");
T("u1c").sp.push("Funzioni trigonometriche: in un triangolo rettangolo con angolo θ, sin θ = cateto opposto / ipotenusa, cos θ = cateto adiacente / ipotenusa, tan θ = sin θ / cos θ = cateto opposto / cateto adiacente. Valori da sapere senza calcolatrice: sin 0° = 0, sin 30° = 0,5, sin 45° ≈ 0,71, sin 60° ≈ 0,87, sin 90° = 1 (per il coseno l'ordine è al contrario); tan 45° = 1. Vale sempre sin²θ + cos²θ = 1. Gli angoli si misurano anche in radianti: 180° = π rad, quindi 90° = π/2 e 60° = π/3.");
T("u1c").sp.push("Differenza di vettori: a − b è la somma di a con il vettore opposto −b (stesso modulo, verso contrario). Serve, per esempio, per la variazione di velocità Δv = v₂ − v₁: una palla che rimbalza a velocità uguale ha |Δv| doppio, non nullo. Con le componenti: si sottraggono separatamente le x e le y.");
T("u1c").es.push({q:"Una forza di 20 N tira un carrello formando 60° con il binario, mentre il carrello si sposta di 5 m lungo il binario. Quanto lavoro compie? E quanto vale |F×s|?",p:["Lavoro = prodotto scalare: L = F·s·cos 60° = 20·5·0,5","Prodotto vettoriale: |F×s| = F·s·sin 60° = 100·0,87"],r:"L = 50 J; |F×s| ≈ 87 (N·m), un vettore perpendicolare sia alla forza sia al binario"});
T("u2c").sp.push("Equilibrio statico e traslazionale: un corpo puntiforme è in equilibrio quando la somma vettoriale di tutte le forze è zero (primo principio): resta fermo o si muove di moto rettilineo uniforme. Si impone ΣFₓ = 0 e ΣF_y = 0. La tensione è la forza con cui un filo teso tira il corpo a cui è attaccato: in un filo ideale (senza massa) è uguale in tutti i punti, e una carrucola ideale ne cambia solo la direzione, come nei sistemi di trazione ortopedica.");
T("u2e").sp.push("Moto del centro di massa: per un sistema di corpi vale M·a_cm = ΣF_esterne. Le forze interne (urti, esplosioni, muscoli che spingono una parte del corpo contro un'altra) si annullano a coppie per il terzo principio e non muovono il centro di massa. Se il sistema è isolato, il centro di massa resta fermo o si muove di moto rettilineo uniforme: un tuffatore può ruotare e piegarsi come vuole, ma il suo baricentro segue comunque una parabola.");
T("u2e").sp.push("Le leve nel corpo umano: le ossa sono le aste, le articolazioni i fulcri, i muscoli applicano la potenza. Il capo in equilibrio sulla colonna è una leva di 1° genere (fulcro tra peso della testa e muscoli del collo); sollevarsi sulle punte dei piedi è di 2° genere (sempre vantaggiosa); la maggior parte delle leve degli arti, come l'avambraccio flesso dal bicipite, è di 3° genere: il muscolo deve fare una forza molte volte maggiore del carico, ma in cambio un piccolo accorciamento del muscolo produce un ampio e rapido movimento della mano.");
T("u2e").es.push({q:"Due masse di 2 kg e 6 kg sono alle estremità di un'asta leggera lunga 2 m. Dove si trova il centro di massa?",p:["Origine sulla massa da 2 kg: x₁ = 0, x₂ = 2 m","x_cm = (2·0 + 6·2)/(2 + 6) = 12/8"],r:"a 1,5 m dalla massa di 2 kg, cioè a 0,5 m da quella di 6 kg"});
T("u3a").es.push({q:"Un manometro a U contiene mercurio (ρ = 13 600 kg/m³). Un ramo è collegato a una bombola, l'altro è aperto; il mercurio è più alto di 5 cm nel ramo aperto. Pressione relativa e assoluta del gas? (g = 10 m/s², p_atm ≈ 1,01·10⁵ Pa)",p:["Il gas spinge il mercurio verso il ramo aperto: la sua pressione supera quella atmosferica","Δp = ρgh = 13 600·10·0,05 = 6800 Pa (cioè 50 mmHg)","p_ass = 1,01·10⁵ + 0,068·10⁵"],r:"pressione relativa 6800 Pa; assoluta circa 1,08·10⁵ Pa"});
T("u3c").sp.push("Flusso e regimi di moto: la portata Q = ΔV/Δt (m³/s) è il volume che attraversa una sezione in un secondo. Il moto è stazionario quando in ogni punto la velocità non cambia nel tempo (le linee di flusso sono fisse); è laminare quando il fluido scorre a strati paralleli che non si mescolano; è turbolento quando compaiono vortici irregolari. Continuità e Bernoulli, nella forma vista qui, valgono per il moto stazionario di un fluido ideale.");
T("u3c").es.push({q:"In un aneurisma la sezione dell'aorta passa da 4 cm² a 8 cm². Il sangue (ρ ≈ 1000 kg/m³) arriva a 0,4 m/s. Velocità nell'aneurisma e variazione di pressione?",p:["Continuità: v₂ = v₁·A₁/A₂ = 0,4·4/8 = 0,2 m/s","Bernoulli (stessa quota): p₂ − p₁ = ½ρ(v₁² − v₂²) = 500·(0,16 − 0,04)"],r:"0,2 m/s; la pressione nel tratto dilatato è maggiore di 60 Pa: la parete viene spinta ancora di più"});
T("u3d").es.push({q:"Un'arteria (resistenza R) alimenta due rami in parallelo, di resistenza 2R e 2R. Resistenza totale? Se la differenza di pressione complessiva è Δp, che portata entra?",p:["Parallelo: 2R e 2R → 1/R_p = 1/(2R) + 1/(2R) → R_p = R","Serie con l'arteria: R_tot = R + R = 2R","Q = Δp/R_tot"],r:"R_tot = 2R e Q = Δp/(2R); ogni ramo riceve metà della portata"});
T("u3e").sp.push("Interfacce piane e curve: attraverso una superficie piana la pressione è la stessa dai due lati; attraverso una superficie curva no, perché la tensione superficiale «stringe» verso il centro di curvatura. Per una sfera (goccia, bolla, alveolo) Δp = 2τ/r; per un cilindro (un vaso sanguigno) la legge di Laplace diventa T = p·r, dove T è la tensione della parete per unità di lunghezza. Conseguenze: a parità di pressione, un vaso più largo ha pareti più tese (per questo un aneurisma tende a peggiorare), mentre i capillari, piccolissimi, reggono con pareti di un solo strato di cellule.");
T("u3e").sp.push("Negli alveoli il problema è opposto: con la stessa τ gli alveoli piccoli avrebbero pressione interna maggiore e si svuoterebbero in quelli grandi. Il surfattante riduce τ, e la riduce di più quando l'alveolo si rimpicciolisce (le sue molecole si addensano): così alveoli di dimensioni diverse restano stabili e respirare richiede meno lavoro. Nei prematuri, che ne producono poco, gli alveoli collassano (sindrome da distress respiratorio).");
T("u4a").sp.push("Pulsazione ed equazione d'onda: un'onda armonica che viaggia lungo x si scrive y(x,t) = A·sin(kx − ωt). La pulsazione ω = 2πf = 2π/T (rad/s) dice quanto velocemente oscilla ogni punto; il numero d'onda k = 2π/λ (rad/m) quante oscillazioni ci sono per metro. La velocità di propagazione è v = ω/k = λ·f. Il segno meno tra kx e ωt indica un'onda che va verso x crescente. Fissato x si vede un'oscillazione nel tempo; fissato t si vede una «fotografia» sinusoidale nello spazio.");
T("u4b").sp.push("Energia e potenza trasportate da un'onda: un'onda armonica trasporta un'energia proporzionale al quadrato dell'ampiezza e al quadrato della pulsazione (E ∝ ω²A²). Per questo, a parità di ampiezza, raddoppiare la frequenza quadruplica la potenza. L'intensità I = P/A (W/m²) è la potenza che attraversa un metro quadrato perpendicolare alla propagazione.");
T("u4b").sp.push("Velocità e percezione del suono: il suono è più veloce nei mezzi più rigidi, circa 340 m/s nell'aria, 1500 m/s nell'acqua e nei tessuti molli, 3000–4000 m/s nell'osso. L'orecchio sente frequenze tra circa 20 Hz e 20 kHz (sotto infrasuoni, sopra ultrasuoni) e intensità tra la soglia di udibilità (10⁻¹² W/m², 0 dB) e la soglia del dolore (circa 1 W/m², 120 dB). La sensazione di volume cresce in modo circa logaritmico: per questo si usano i decibel.");
T("u4d").es.push({q:"Due altoparlanti in fase emettono una nota di 680 Hz (suono a 340 m/s). Un ascoltatore dista 3 m da uno e 3,75 m dall'altro. Che cosa sente?",p:["λ = v/f = 340/680 = 0,5 m","Differenza di cammino: 0,75 m = 1,5·λ","Multiplo dispari di λ/2 → opposizione di fase"],r:"interferenza distruttiva: il suono in quel punto è molto attenuato"});
T("u5d").sp.push("Ciclo di Carnot: è il ciclo reversibile ideale formato da quattro trasformazioni, un'espansione isoterma alla temperatura calda (il gas assorbe Q_c), un'espansione adiabatica (si raffredda fino a T_f), una compressione isoterma alla temperatura fredda (cede Q_f) e una compressione adiabatica che lo riporta allo stato iniziale. Nessuna macchina che lavora tra le stesse due temperature può avere rendimento maggiore: η = 1 − T_f/T_c. Le macchine reali, irreversibili, stanno sempre sotto.");
T("u5d").sp.push("Interpretazione statistica dell'entropia: uno stato macroscopico (per esempio «gas distribuito in tutta la stanza») può essere realizzato da un numero W di disposizioni microscopiche delle molecole. Boltzmann ha mostrato che S = k·ln W. Gli stati disordinati hanno un numero enormemente maggiore di microstati di quelli ordinati, quindi un sistema isolato evolve quasi con certezza verso di essi: il gas si espande nel vuoto, il caldo e il freddo si mescolano, l'inchiostro si diffonde, e il contrario non si osserva mai. È questa la direzione dei processi spontanei.");
T("u5d").es.push({q:"Un gas può distribuirsi in due metà di un recipiente. Con 4 molecole, quante disposizioni mettono tutte le molecole a sinistra e quante ne mettono 2 per parte?",p:["Ogni molecola ha 2 possibilità: 2⁴ = 16 disposizioni in tutto","Tutte a sinistra: 1 sola disposizione","2 e 2: si scelgono 2 molecole su 4, cioè 6 disposizioni"],r:"1 contro 6: già con 4 molecole lo stato uniforme è 6 volte più probabile; con 10²³ molecole lo stato «tutte da una parte» è praticamente impossibile"});
T("u6a").sp.push("Induzione e polarizzazione: in un conduttore gli elettroni liberi si spostano. Avvicinando una bacchetta positiva a una sfera metallica gli elettroni si accumulano dal lato vicino e lasciano positivo quello lontano; se a quel punto si collega la sfera a terra, salgono altri elettroni, e staccando il collegamento la sfera resta carica negativamente (carica per induzione). In un isolante (dielettrico) gli elettroni non sono liberi: ogni molecola si deforma o si orienta diventando un piccolo dipolo (polarizzazione). Per questo un pettine strofinato attira i pezzetti di carta e un sottile getto d'acqua: la parte vicina ha carica opposta, e l'attrazione vince la repulsione perché è più vicina.");
T("u6b").sp.push("Moto di una carica in un campo uniforme: la forza F = qE è costante, quindi l'accelerazione a = qE/m è costante, come per un sasso nel campo di gravità. Se la carica parte ferma o si muove lungo le linee di campo il moto è rettilineo uniformemente accelerato (una carica positiva accelera nel verso di E, una negativa in verso opposto). Se entra perpendicolarmente al campo, come gli elettroni tra le placche di deflessione di un oscilloscopio, la traiettoria è una parabola. Per la velocità finale conviene la conservazione dell'energia: ½mv² = q·ΔV.");
T("u6b").es.push({q:"Un elettrone (q = 1,6·10⁻¹⁹ C, m ≈ 9·10⁻³¹ kg) è tra due armature distanti 1 cm con una d.d.p. di 90 V. Campo, forza e accelerazione?",p:["E = ΔV/d = 90/0,01 = 9000 V/m","F = eE = 1,6·10⁻¹⁹·9·10³ ≈ 1,44·10⁻¹⁵ N","a = F/m = 1,44·10⁻¹⁵ / 9·10⁻³¹ = 1,6·10¹⁵ m/s²"],r:"9000 V/m; circa 1,4·10⁻¹⁵ N verso l'armatura positiva; 1,6·10¹⁵ m/s²: il peso dell'elettrone è del tutto trascurabile"});
T("u6c").es.push({q:"Tre condensatori da 6 µF ciascuno: quanto valgono le capacità equivalenti tutti in serie e tutti in parallelo? In serie a 12 V, che tensione c'è su ciascuno?",p:["Serie: 1/C = 3/6 → C = 2 µF","Parallelo: C = 6 + 6 + 6 = 18 µF","In serie la carica è la stessa: Q = 2 µF·12 V = 24 µC; su ciascuno V = Q/C = 24/6"],r:"2 µF in serie, 18 µF in parallelo; 4 V su ciascuno"});
T("u6e").sp.push("Campo magnetico delle correnti (Oersted): un filo rettilineo percorso da corrente genera un campo le cui linee sono circonferenze concentriche attorno al filo; il verso si trova con la regola della mano destra (pollice nel verso della corrente, le dita piegate danno il verso di B). L'intensità cresce con la corrente e diminuisce con la distanza: B = µ₀I/(2πr). Avvolgendo il filo a spirale (solenoide) si ottiene all'interno un campo quasi uniforme, come nelle bobine della risonanza magnetica.");
T("u6e").sp.push("Legge di Lenz in pratica: la corrente indotta crea un campo che si oppone alla variazione del flusso, non al flusso in sé. Se avvicini il polo nord di un magnete a una spira il flusso aumenta, e la spira presenta a sua volta un polo nord verso il magnete per respingerlo; se lo allontani il flusso cala e la spira lo trattiene (polo sud verso il magnete). È una conseguenza della conservazione dell'energia: per indurre corrente bisogna compiere lavoro contro questa opposizione.");
T("u7a").sp.push("Ampiezza e intensità di un'onda elettromagnetica: l'ampiezza è il valore massimo dei campi oscillanti E e B; l'intensità (W/m²) è proporzionale al quadrato dell'ampiezza del campo elettrico. Intensità e colore sono cose diverse: l'intensità dice quanti fotoni arrivano, la frequenza quanta energia porta ciascuno. Per una sorgente puntiforme anche la luce segue la legge dell'inverso del quadrato.");
T("u7a").sp.push("Spettro in medicina: onde radio (risonanza magnetica), microonde (diatermia, riscaldamento dei tessuti), infrarosso (termografia, termometri senza contatto), visibile (occhio, endoscopia, laser), ultravioletto (sintesi di vitamina D, sterilizzazione, ma anche eritemi e tumori cutanei), raggi X (radiografia, TAC), raggi γ (medicina nucleare, radioterapia). Sono non ionizzanti radio, microonde, IR e visibile; ionizzanti l'UV di alta energia, gli X e i γ, oltre alle radiazioni corpuscolari α e β. Le radiazioni ionizzanti possono rompere legami chimici e danneggiare il DNA: per questo si limitano le dosi.");
T("u7c").sp.push("Come usare l'equazione dei punti coniugati: 1/p + 1/q = 1/f con tutte le distanze nella stessa unità. Se q risulta positivo l'immagine è reale (dall'altra parte della lente, si può raccogliere su uno schermo); se risulta negativo è virtuale (dalla stessa parte dell'oggetto, si vede solo guardando attraverso la lente). L'ingrandimento m = −q/p dà insieme grandezza e orientamento: |m| > 1 ingrandita, |m| < 1 rimpicciolita; m negativo capovolta, positivo diritta. Caso utile: con l'oggetto a 2f l'immagine è a 2f, capovolta e della stessa grandezza.");
T("u7c").es.push({q:"Una lente convergente con f = 20 cm guarda un francobollo posto a 10 cm. Dove si forma l'immagine e com'è?",p:["1/q = 1/f − 1/p = 1/20 − 1/10 = −1/20","q = −20 cm: negativo → immagine virtuale, dalla stessa parte del francobollo","m = −q/p = 20/10 = +2"],r:"immagine virtuale, diritta, ingrandita 2 volte: è la lente d'ingrandimento"});
T("u7d").es.push({q:"Una soluzione in una cuvetta da 1 cm trasmette il 10% della luce. Quale percentuale trasmette con una cuvetta da 2 cm? E con concentrazione dimezzata nella cuvetta da 1 cm?",p:["T = 10% → A = 1","Cuvetta doppia: A = 2 → T = 10⁻² = 1%","Concentrazione metà: A = 0,5 → T = 10^(−0,5) ≈ 0,32"],r:"1% con la cuvetta da 2 cm; circa 32% con concentrazione dimezzata (non il 20%)"});
T("u7e").es.push({q:"Il fluoro-18 usato nella PET ha emivita di circa 110 minuti. Una dose ha attività 400 MBq alle 8:00. Che attività ha alle 11:40?",p:["Tempo trascorso: 3 h 40 min = 220 min","220/110 = 2 emivite","400/2² = 400/4"],r:"100 MBq"});
})();
